mapper.select:
select  
l.plant_cd = #{plantCd}
order by l.plant_cd, l.labeler_cd

mapper.update:
update wms_labeler
   set labeler_nm = #{f.labelerNm}, terminal_id = #{f.terminalId}, conn_mode = #{f.connMode}, tpl_id = #{f.tplId},
       deadline_ms = #{f.deadlineMs}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where labeler_id = #{id} and row_ver = #{f.rowVer}

mapper.sql:
  from wms_labeler_box b
  join mst_item i on i.item_id = b.item_id
 where b.created_at >= #{q.fromAt} and b.created_at < #{q.toAt}
and b.plant_cd = #{q.plantCd}
and b.status = #{q.status}
and (b.box_cd ilike #{q.boxLike} escape '\' or b.sscc like #{q.boxLike} escape '\'
                                  or b.ref_no ilike #{q.boxLike} escape '\')

mapper.select:
select log_id, labeler_id, event_cd, code, detail, reply_cd, occurred_at
  from wms_labeler_dev_log where labeler_id = #{labelerId}
 order by log_id desc limit #{limit}
